PRAGMA foreign_keys=OFF;
CREATE TABLE `worker_profiles` (`user_id` text PRIMARY KEY NOT NULL REFERENCES `user`(`id`),`phone` text,`notes` text,`must_change_password` integer DEFAULT 1 NOT NULL,`last_login_at` integer,`created_by` text REFERENCES `user`(`id`),`updated_by` text REFERENCES `user`(`id`),`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `worker_permissions` (`id` text PRIMARY KEY NOT NULL,`user_id` text NOT NULL REFERENCES `user`(`id`) ON DELETE CASCADE,`permission` text NOT NULL,`allowed` integer NOT NULL,`updated_by` text REFERENCES `user`(`id`),`updated_at` integer NOT NULL);
CREATE UNIQUE INDEX `worker_permission_user_idx` ON `worker_permissions` (`user_id`,`permission`);
CREATE TABLE `product_price_history` (`id` text PRIMARY KEY NOT NULL,`product_id` text NOT NULL REFERENCES `products`(`id`),`price_type` text NOT NULL,`old_value_cents` integer NOT NULL,`new_value_cents` integer NOT NULL,`reason` text NOT NULL,`changed_by` text NOT NULL REFERENCES `user`(`id`),`created_at` integer NOT NULL);
CREATE INDEX `price_history_product_idx` ON `product_price_history` (`product_id`,`created_at`);
CREATE TABLE `supplier_payments` (`id` text PRIMARY KEY NOT NULL,`supplier_id` text NOT NULL REFERENCES `suppliers`(`id`),`amount_cents` integer NOT NULL CHECK (`amount_cents` > 0),`cash_register_id` text NOT NULL REFERENCES `cash_registers`(`id`),`purchase_id` text REFERENCES `purchases`(`id`),`notes` text,`created_by` text NOT NULL REFERENCES `user`(`id`),`created_at` integer NOT NULL);
CREATE INDEX `supplier_payments_supplier_idx` ON `supplier_payments` (`supplier_id`,`created_at`);
CREATE TABLE `inventory_sessions` (`id` text PRIMARY KEY NOT NULL,`status` text DEFAULT 'draft' NOT NULL,`reason` text,`created_by` text NOT NULL REFERENCES `user`(`id`),`created_at` integer NOT NULL,`completed_at` integer);
CREATE TABLE `inventory_items` (`id` text PRIMARY KEY NOT NULL,`session_id` text NOT NULL REFERENCES `inventory_sessions`(`id`),`product_id` text NOT NULL REFERENCES `products`(`id`),`expected_quantity` integer NOT NULL,`counted_quantity` integer DEFAULT 0 NOT NULL);
CREATE UNIQUE INDEX `inventory_item_session_idx` ON `inventory_items` (`session_id`,`product_id`);
CREATE INDEX `products_barcode_lookup_idx` ON `products` (`manufacturer_barcode`,`internal_barcode`,`internal_qr`);
CREATE INDEX `customers_search_idx` ON `customers` (`name`,`phone`);
CREATE INDEX `purchases_date_idx` ON `purchases` (`created_at`);
CREATE INDEX `stock_movements_date_idx` ON `stock_movements` (`created_at`);
ALTER TABLE `products` ADD COLUMN `description` text;
ALTER TABLE `purchases` ADD COLUMN `idempotency_key` text;
ALTER TABLE `purchases` ADD COLUMN `notes` text;
CREATE UNIQUE INDEX `purchases_idempotency_idx` ON `purchases` (`idempotency_key`);
ALTER TABLE `daily_closings` ADD COLUMN `register_id` text REFERENCES `cash_registers`(`id`);
CREATE UNIQUE INDEX `daily_closings_register_idx` ON `daily_closings` (`register_id`);
UPDATE `user` SET `role`='global_admin' WHERE `role`='owner';
PRAGMA foreign_keys=ON;
